4/5;background:#fff;overflow:hidden;display:grid;place-items:center;cursor:pointer;position:relative}.photo img{width:100%;height:100%;object-fit:contain;display:block}.photo i{font-size:42px;color:#4fd5ef}.body{padding:19px}.body h2{font-size:19px;margin:0}.role{margin:7px 0;color:#5dc7df;font-size:11px;font-weight:800}.bio{margin:13px 0;color:#89a8b2;font-size:10px;line-height:1.7}.bio-preview{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:6;overflow:hidden;max-height:102px}.bio-full{display:none;margin:13px 0;color:#89a8b2;font-size:10px;line-height:1.7}.bio-full.open{display:block}.bio-more{display:inline-flex;align-items:center;gap:6px;margin-top:2px;padding:7px 10px;border:1px solid var(--line);border-radius:9px;background:rgba(67,209,240,.05);color:#75d9eb;font-size:9px;font-weight:800;cursor:pointer}.bio-more:hover{background:rgba(67,209,240,.1);color:#fff}.contact-list{display:grid;gap:7px;padding:13px 0;border-top:1px solid rgba(86,210,238,.09);border-bottom:1px solid rgba(86,210,238,.09)}.contact{display:flex;align-items:center;gap:8px;color:#9db7c0;text-decoration:none;font-size:10px}.contact i{width:24px;height:24px;display:grid;place-items:center;border-radius:8px;background:rgba(67,209,240,.06);color:#58cee8}.actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:12px}.action{display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 8px;border-radius:10px;text-decoration:none;font-size:9px;font-weight:800;border:1px solid var(--line);color:#b9d8df}.action.primary{background:linear-gradient(135deg,#2db1cf,#17758d);color:#fff}.empty{border:1px dashed var(--line);border-radius:18px;padding:55px 20px;text-align:center;color:var(--muted);grid-column:1/-1}.lightbox{position:fixed;inset:0;z-index:100;background:rgba(0,6,10,.94);backdrop-filter:blur(14px);display:none;align-items:center;justify-content:center;padding:18px}.lightbox.open{display:flex}.lightbox-content{max-width:96vw;max-height:90vh;overflow:hidden;display:flex;align-items:center;justify-content:center}.lightbox img{max-width:90vw;max-height:82vh;width:auto;height:auto;object-fit:contain;border-radius:12px;box-shadow:0 25px 80px rgba(0,0,0,.55);transform:scale(1);transition:transform .15s ease;touch-action:none}.zoom-controls{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);display:flex;gap:6px;padding:6px;border:1px solid rgba(255,255,255,.12);border-radius:14px;background:rgba(2,11,18,.82);backdrop-filter:blur(12px)}.zoom-controls button,.lightbox-close{width:40px;height:40px;border:1px solid rgba(255,255,255,.14);border-radius:10px;background:rgba(255,255,255,.05);color:#fff;cursor:pointer}.lightbox-close{position:fixed;top:18px;right:18px;font-size:18px}.zoom-level{min-width:52px;display:grid;place-items:center;color:#9db7c0;font-size:9px}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.shell{width:calc(100% - 24px)}main{padding:40px 0}.grid{grid-template-columns:1fr}.lightbox img{max-width:94vw;max-height:78vh}.lightbox-close{top:12px;right:12px}}</style></head><body><header class="header"><div class="shell nav"><a class="brand" href="{{ route('home') }}">@if($logo)<img src="{{ asset('storage/'.$logo) }}" alt="{{ $name }}">@endif<strong>{{ $name }}</strong></a><a class="back" href="{{ route('home') }}"><i class="fa-solid fa-arrow-left"></i> Back to website</a></div></header><main class="shell"><section class="hero"><span class="eyebrow">Leadership &amp; Management</span><h1>Management Team</h1><p>Meet the people responsible for guiding {{ $name }}.</p></section><section class="grid">@forelse($members as $member)<article class="card"><div class="photo" @if($member->image_path) data-image="{{ asset('storage/'.$member->image_path) }}" data-name="{{ $member->title }}" role="button" tabindex="0" @endif>@if($member->image_path)<img src="{{ asset('storage/'.$member->image_path) }}" alt="{{ $member->title }}" loading="lazy">@else<i class="fa-solid fa-user-tie"></i>@endif</div><div class="body"><h2>{{ $member->title }}</h2><div class="role">{{ $member->designation ?: $member->excerpt }}</div>@if($member->content)<div class="bio bio-preview" id="bio-preview-{{ $member->id }}">{!! nl2br(e($member->content)) !!}</div><div class="bio-full" id="bio-full-{{ $member->id }}">{!! nl2br(e($member->content)) !!}</div><button class="bio-more" type="button" data-more="{{ $member->id }}"><span>More</span><i class="fa-solid fa-chevron-down"></i></button>@endif<div class="contact-list"><a class="contact" href="tel:{{ preg_replace('/[^0-9+]/','',$member->phone) }}"><i class="fa-solid fa-phone"></i>{{ $member->phone }}</a>@if($member->email)<a class="contact" href="mailto:{{ $member->email }}"><i class="fa-solid fa-envelope"></i>{{ $member->email }}</a>@endif</div><div class="actions"><a class="action primary" href="{{ route('management.vcard',$member) }}"><i class="fa-solid fa-user-plus"></i> Add to Contacts</a>@if($member->visiting_card_path)<a class="action" href="{{ asset('storage/'.$member->visiting_card_path) }}" target="_blank"><i class="fa-regular fa-address-card"></i> Visiting Card</a>@else<a class="action" href="tel:{{ preg_replace('/[^0-9+]/','',$member->phone) }}"><i class="fa-solid fa-phone"></i> Call</a>@endif</div></div></article>@empty<div class="empty"><i class="fa-solid fa-people-group"></i></div>@endforelse</section></main><div class="lightbox" id="photoLightbox"><button class="lightbox-close" id="lightboxClose" type="button"><i class="fa-solid fa-xmark"></i></button><div class="lightbox-content"><img id="lightboxImage" src="" alt=""></div><div class="zoom-controls"><button id="zoomOut" type="button"><i class="fa-solid fa-minus"></i></button><span class="zoom-level" id="zoomLevel">100%</span><button id="zoomIn" type="button"><i class="fa-solid fa-plus"></i></button><button id="zoomReset" type="button"><i class="fa-solid fa-rotate-left"></i></button></div></div><script>(function(){const buttons=[...document.querySelectorAll('.bio-more')];function closeOther(except){buttons.forEach(btn=>{if(btn===except)return;const id=btn.dataset.more,full=document.getElementById('bio-full-'+id),preview=document.getElementById('bio-preview-'+id);if(full&&full.classList.contains('open')){full.classList.remove('open');preview.style.display='';btn.querySelector('span').textContent='More';btn.querySelector('i').className='fa-solid fa-chevron-down'}})}buttons.forEach(btn=>btn.addEventListener('click',()=>{const id=btn.dataset.more,full=document.getElementById('bio-full-'+id),preview=document.getElementById('bio-preview-'+id),open=!full.classList.contains('open');if(open)closeOther(btn);full.classList.toggle('open',open);preview.style.display=open?'none':'';btn.querySelector('span').textContent=open?'Less':'More';btn.querySelector('i').className=open?'fa-solid fa-chevron-up':'fa-solid fa-chevron-down'}));const box=document.getElementById('photoLightbox'),img=document.getElementById('lightboxImage'),close=document.getElementById('lightboxClose'),level=document.getElementById('zoomLevel');let zoom=1;function render(){zoom=Math.min(4,Math.max(1,zoom));img.style.transform='scale('+zoom+')';level.textContent=Math.round(zoom*100)+'%'}function open(p){img.src=p.dataset.image;img.alt=p.dataset.name||'';zoom=1;render();box.classList.add('open');document.body.style.overflow='hidden'}function shut(){box.classList.remove('open');img.src='';document.body.style.overflow=''}document.querySelectorAll('.photo[data-image]').forEach(p=>{p.onclick=()=>open(p);p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(p)}}});document.getElementById('zoomIn').onclick=()=>{zoom+=.25;render()};document.getElementById('zoomOut').onclick=()=>{zoom-=.25;render()};document.getElementById('zoomReset').onclick=()=>{zoom=1;render()};close.onclick=shut;box.onclick=e=>{if(e.target===box)shut()};document.addEventListener('keydown',e=>{if(e.key==='Escape')shut()})})();</script></body></html>